1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.clube.NivelClube;
4	import com.loja.checkout.cupom.Cupom;
5	import com.loja.checkout.dto.ItemRequest;
6	import com.loja.checkout.dto.PedidoRequest;
7	import com.loja.checkout.dto.ResumoResponse;
8	import com.loja.checkout.entrega.ModalidadeEntrega;
9	import com.loja.checkout.exception.CheckoutException;
10	import com.loja.checkout.pagamento.FormaPagamento;
11	import com.loja.checkout.pagamento.ResultadoPagamento;
12	import com.loja.checkout.regiao.Regiao;
13	import org.springframework.stereotype.Service;
14	
15	import java.math.BigDecimal;
16	import java.math.RoundingMode;
17	import java.util.List;
18	import java.util.Map;
19	import java.util.function.Function;
20	import java.util.stream.Collectors;
21	
22	@Service
23	public class CheckoutService {
24	
25	    private final Map<String, ModalidadeEntrega> modalidades;
26	    private final Map<String, Cupom> cupons;
27	    private final Map<String, NivelClube> niveis;
28	    private final Map<String, FormaPagamento> pagamentos;
29	
30	    public CheckoutService(List<ModalidadeEntrega> modalidadesList,
31	                           List<Cupom> cuponsList,
32	                           List<NivelClube> niveisList,
33	                           List<FormaPagamento> pagamentosList) {
34	        this.modalidades = modalidadesList.stream()
35	                .collect(Collectors.toMap(ModalidadeEntrega::codigo, Function.identity()));
36	        this.cupons = cuponsList.stream()
37	                .collect(Collectors.toMap(Cupom::codigo, Function.identity()));
38	        this.niveis = niveisList.stream()
39	                .collect(Collectors.toMap(NivelClube::codigo, Function.identity()));
40	        this.pagamentos = pagamentosList.stream()
41	                .collect(Collectors.toMap(FormaPagamento::codigo, Function.identity()));
42	    }
43	
44	    public ResumoResponse calcular(PedidoRequest pedido) {
45	        validarItens(pedido.itens());
46	
47	        NivelClube nivel = niveis.get(pedido.nivelClube());
48	        if (nivel == null) throw new CheckoutException("NIVEL_CLUBE_INVALIDO");
49	
50	        Regiao regiao = resolverRegiao(pedido.regiao());
51	
52	        ModalidadeEntrega entrega = modalidades.get(pedido.modalidadeEntrega());
53	        if (entrega == null) throw new CheckoutException("MODALIDADE_INVALIDA");
54	
55	        BigDecimal pesoTotal = calcularPeso(pedido.itens());
56	        if (!entrega.disponivel(pesoTotal)) throw new CheckoutException("MODALIDADE_INDISPONIVEL");
57	
58	        BigDecimal subtotal = calcularSubtotal(pedido.itens());
59	
60	        Cupom cupom = resolverCupom(pedido.cupom(), subtotal, pedido.itens());
61	
62	        FormaPagamento pagamento = pagamentos.get(pedido.formaPagamento());
63	        if (pagamento == null) throw new CheckoutException("FORMA_PAGAMENTO_INVALIDA");
64	
65	        int parcelas = pedido.parcelas() != null ? pedido.parcelas() : 1;
66	        if (!pagamento.parcelamentoValido(parcelas)) throw new CheckoutException("PARCELAMENTO_INVALIDO");
67	
68	        BigDecimal frete = arredondar(entrega.calcularFrete(pesoTotal));
69	        if (nivel.freteGratis()) frete = BigDecimal.ZERO.setScale(2);
70	
71	        BigDecimal desconto = BigDecimal.ZERO.setScale(2);
72	        if (cupom != null) {
73	            desconto = cupom.calcularDesconto(pedido.itens(), subtotal, frete);
74	        }
75	
76	        BigDecimal seguro = regiao.calcularSeguro(subtotal);
77	        BigDecimal totalPedido = subtotal.subtract(desconto).add(frete).add(seguro);
78	
79	        if (!pagamento.disponivel(totalPedido)) throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
80	
81	        ResultadoPagamento resultado = pagamento.calcular(totalPedido, parcelas);
82	        BigDecimal ajuste = resultado.totalFinal().subtract(totalPedido);
83	
84	        BigDecimal credito = arredondar(subtotal.multiply(nivel.percentualCredito()));
85	        boolean brinde = nivel.brinde(subtotal);
86	
87	        return new ResumoResponse(
88	                subtotal, desconto, frete, entrega.prazoDias(), seguro,
89	                ajuste, resultado.totalFinal(), parcelas, resultado.valorParcela(),
90	                credito, brinde);
91	    }
92	
93	    private void validarItens(List<ItemRequest> itens) {
94	        if (itens == null || itens.isEmpty()) throw new CheckoutException("PEDIDO_INVALIDO");
95	        for (ItemRequest item : itens) {
96	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0
97	                    || item.quantidade() == null || item.quantidade() <= 0
98	                    || item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
99	                throw new CheckoutException("PEDIDO_INVALIDO");
100	            }
101	        }
102	    }
103	
104	    private Regiao resolverRegiao(String codigo) {
105	        if (codigo == null) throw new CheckoutException("REGIAO_INVALIDA");
106	        try {
107	            return Regiao.valueOf(codigo);
108	        } catch (IllegalArgumentException e) {
109	            throw new CheckoutException("REGIAO_INVALIDA");
110	        }
111	    }
112	
113	    private Cupom resolverCupom(String codigo, BigDecimal subtotal, List<ItemRequest> itens) {
114	        if (codigo == null || codigo.isBlank()) return null;
115	        Cupom cupom = cupons.get(codigo);
116	        if (cupom == null) throw new CheckoutException("CUPOM_INVALIDO");
117	        if (!cupom.aplicavel(itens, subtotal)) throw new CheckoutException("CUPOM_NAO_APLICAVEL");
118	        return cupom;
119	    }
120	
121	    private BigDecimal calcularPeso(List<ItemRequest> itens) {
122	        BigDecimal peso = BigDecimal.ZERO;
123	        for (ItemRequest item : itens) {
124	            peso = peso.add(item.pesoKg().multiply(new BigDecimal(item.quantidade())));
125	        }
126	        return peso;
127	    }
128	
129	    private BigDecimal calcularSubtotal(List<ItemRequest> itens) {
130	        BigDecimal subtotal = BigDecimal.ZERO;
131	        for (ItemRequest item : itens) {
132	            subtotal = subtotal.add(item.precoUnitario().multiply(new BigDecimal(item.quantidade())));
133	        }
134	        return arredondar(subtotal);
135	    }
136	
137	    private static BigDecimal arredondar(BigDecimal valor) {
138	        return valor.setScale(2, RoundingMode.HALF_EVEN);
139	    }
140	}
