2	
3	import org.springframework.stereotype.Component;
4	
5	import java.math.BigDecimal;
6	import java.math.RoundingMode;
7	
8	@Component
9	public class Cartao implements FormaPagamento {
10	
11	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
12	    private static final int MAX_SEM_JUROS = 3;
13	    private static final int MAX_PARCELAS = 12;
14	
15	    @Override
16	    public String codigo() {
17	        return "CARTAO";
18	    }
19	
20	    @Override
21	    public boolean parcelamentoValido(int parcelas) {
22	        return parcelas >= 1 && parcelas <= MAX_PARCELAS;
23	    }
24	
25	    @Override
26	    public boolean disponivel(BigDecimal totalPedido) {
27	        return true;
28	    }
29	
30	    @Override
31	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
32	        if (parcelas <= MAX_SEM_JUROS) {
33	            BigDecimal valorParcela = totalPedido.divide(new BigDecimal(parcelas), 2, RoundingMode.HALF_EVEN);
34	            return new ResultadoPagamento(totalPedido, valorParcela);
35	        }
36	        BigDecimal umMaisTaxa = BigDecimal.ONE.add(TAXA_MENSAL);
37	        BigDecimal potencia = umMaisTaxa.pow(parcelas);
38	        BigDecimal potenciaNeg = BigDecimal.ONE.divide(potencia, 20, RoundingMode.HALF_EVEN);
39	        BigDecimal denominador = BigDecimal.ONE.subtract(potenciaNeg);
40	        BigDecimal valorParcela = totalPedido.multiply(TAXA_MENSAL)
41	                .divide(denominador, 2, RoundingMode.HALF_EVEN);
42	        BigDecimal totalFinal = valorParcela.multiply(new BigDecimal(parcelas));
43	        return new ResultadoPagamento(totalFinal, valorParcela);
44	    }
45	}
